        default:
                return new PayloadLayer(data, dataLen, prevLayer, packet);
        }

        if (be16toh(hdr->serviceID) == 0xFFFF && be16toh(hdr->methodID) == 0x8100)
        {
                return new SomeIpSdLayer(data, dataLen, prevLayer, packet);
